// Task-status: query gateway_tasks via Supabase
// Matches pipeline Auth node pattern: access input.body for webhook POST body
const input = $input.first().json;
const bodyData = input.body || input;  // webhook wraps body in input.body
const token = (bodyData.token || '').replace(/^sk-/, '');
const taskId = bodyData.task_id || '';

const SB_URL = 'https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY = 'process.env.SUPABASE_SERVICE_ROLE_KEY||''';

if (!taskId) {
  return [{ json: { task: { task_id: '', status: 'missing_id', result_json: {} } } }];
}

// Query gateway_tasks
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: SB_URL + '/rest/v1/gateway_tasks?select=task_id,status,result_json&task_id=eq.' + encodeURIComponent(taskId) + '&order=created_at.desc&limit=1',
    headers: { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY },
    json: true, returnFullResponse: true, timeout: 10000
  });
  const rows = resp.body || [];
  if (rows.length === 0) {
    return [{ json: { task: { task_id: taskId, status: 'not_found', result_json: {} } } }];
  }
  const row = rows[0];
  return [{
    json: {
      task: {
        task_id: row.task_id,
        status: row.status || 'unknown',
        result_json: row.result_json || {}
      }
    }
  }];
} catch(e) {
  return [{ json: { error: 'query_failed', task_id: taskId, msg: String(e.message||e).slice(0,200) } }];
}
